# region: fold
def fold(raw):
    out = []
    for tok in raw[1:]:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs, factor=10):
    return [v * factor for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(gather(sift(intake(shape(fold(raw))))))

